### Honor the package thumbnail relationship first
**Severity:** `high`

Resolve the package-declared thumbnail before applying filename heuristics. Otherwise a package that contains both a relationship target and an unrelated `thumbnail*.png` can render the wrong image.

```suggestion
        private static ZipArchiveEntry FindThumbnailEntry(ZipArchive archive)
        {
            foreach (var target in GetThumbnailTargetsFromRelationships(archive))
            {
                var entry = archive.GetEntry(target) ??
                            archive.Entries.FirstOrDefault(e =>
                                string.Equals(e.FullName.Replace('\\', '/'), target.TrimStart('/'), StringComparison.OrdinalIgnoreCase));

                if (entry != null)
                {
                    return entry;
                }
            }

            ZipArchiveEntry namedThumbnail = null;
            ZipArchiveEntry metadataFallback = null;

            foreach (var entry in archive.Entries)
            {
                var name = entry.FullName.Replace('\\', '/');
                var fileName = name.Contains('/') ? name[(name.LastIndexOf('/') + 1)..] : name;

                if (ThumbnailExtensions.Any(ext => name.EndsWith(ext, StringComparison.OrdinalIgnoreCase)) &&
                    fileName.Contains("thumbnail", StringComparison.OrdinalIgnoreCase))
                {
                    namedThumbnail ??= entry;
                    continue;
                }

                if (metadataFallback == null &&
                    name.StartsWith("Metadata/", StringComparison.OrdinalIgnoreCase) &&
                    ThumbnailExtensions.Any(ext => name.EndsWith(ext, StringComparison.OrdinalIgnoreCase)))
                {
                    metadataFallback = entry;
                }
            }

            return namedThumbnail ?? metadataFallback;
        }
```

### Keep fitting images at their size and detach returned bitmaps
**Severity:** `medium`

Do not upscale a fitting image, and return a bitmap that is independent of any source stream whose lifetime is ending.

```suggestion
        public static Bitmap ResizeImage(Bitmap image, uint maxSize)
        {
            if (image == null || maxSize == 0 || maxSize > MaxThumbnailSize)
            {
                return null;
            }

            if (image.Width <= maxSize && image.Height <= maxSize && image.PixelFormat == PixelFormat.Format32bppArgb)
            {
                var detachedImage = new Bitmap(image);
                image.Dispose();
                return detachedImage;
            }

            float scale = Math.Min(1f, Math.Min((float)maxSize / image.Width, (float)maxSize / image.Height));
            int scaleWidth = (int)(image.Width * scale);
            int scaleHeight = (int)(image.Height * scale);

            if (scaleWidth <= 0 || scaleHeight <= 0)
            {
                return null;
            }

            Bitmap destImage = new Bitmap(scaleWidth, scaleHeight, PixelFormat.Format32bppArgb);
            destImage.SetResolution(image.HorizontalResolution, image.VerticalResolution);

            using (var graphics = Graphics.FromImage(destImage))
            {
                graphics.CompositingMode = CompositingMode.SourceCopy;
                graphics.CompositingQuality = CompositingQuality.HighQuality;
                graphics.InterpolationMode = InterpolationMode.HighQualityBicubic;
                graphics.SmoothingMode = SmoothingMode.HighQuality;
                graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;
                graphics.DrawImage(image, 0, 0, scaleWidth, scaleHeight);
            }

            image.Dispose();
            return destImage;
        }
```

### Derive the output path from the file extension
**Severity:** `medium`

Replace only the input extension and keep the output format consistent with the provider contract. A path component can legitimately contain `.3mf` and must not be rewritten.

```suggestion
// Copyright (c) Microsoft Corporation
