// See the LICENSE file in the project root for more information.
using System.Globalization;
using System.IO;

namespace Microsoft.PowerToys.ThumbnailHandler.ThreeMf
{
    internal static class Program
    {
        private static ThreeMfThumbnailProvider _thumbnailProvider;

        [STAThread]
        public static void Main(string[] args)
        {
            ApplicationConfiguration.Initialize();
            if (args != null)
            {
                if (args.Length == 2)
                {
                    string filePath = args[0];
                    uint cx = Convert.ToUInt32(args[1], 10);

                    _thumbnailProvider = new ThreeMfThumbnailProvider(filePath);
                    Bitmap thumbnail = _thumbnailProvider.GetThumbnail(cx);
                    if (thumbnail != null)
                    {
                        filePath = Path.ChangeExtension(filePath, ".png");
                        thumbnail.Save(filePath, System.Drawing.Imaging.ImageFormat.Png);
                    }
                }
                else
                {
                    MessageBox.Show("ThreeMf thumbnail - wrong number of args: " + args.Length.ToString(CultureInfo.InvariantCulture));
                }
            }
        }
    }
}
```
